from qiskit import QuantumCircuit


def steane_encode(logical_bit: int):
    qc = QuantumCircuit(7, 7)
    qc.h(0); qc.h(1); qc.h(3)
    qc.cx(0, 2); qc.cx(3, 5); qc.cx(1, 6)
    qc.cx(0, 4); qc.cx(3, 6); qc.cx(1, 5)
    qc.cx(0, 6); qc.cx(1, 2); qc.cx(3, 4)
    if logical_bit == 1:
        for i in range(7):
            qc.x(i)
    for i in range(7):
        qc.measure(i, i)
    return qc
